### Python

```python
import sys
sys.setrecursionlimit(10000)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    a = [list(next(it).strip()) for _ in range(n)]
    ans = [[0] * m for _ in range(n)]

    parent = [0] * (n * m)

    def find(x):
        # 路径压缩
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx != ry:
            parent[rx] = ry

    # 遍历每个格子
    for i in range(n):
        for j in range(m):
            tmp = a[i][j]
            a[i][j] = 'W'  # 临时变为水域

            # 初始化并查集
            for k in range(n * m):
                parent[k] = k

            # 合并相邻岩石
            for x in range(n):
                for y in range(m):
                    if a[x][y] == 'R':
                        idx = x * m + y
                        if x > 0 and a[x-1][y] == 'R':
                            union(idx, (x-1)*m + y)
                        if y > 0 and a[x][y-1] == 'R':
                            union(idx, x*m + (y-1))

            # 统计连通块数量
            seen = [False] * (n * m)
            cnt = 0
            for x in range(n):
                for y in range(m):
                    if a[x][y] == 'R':
                        root = find(x * m + y)
                        if not seen[root]:
                            seen[root] = True
                            cnt += 1
            ans[i][j] = cnt
            a[i][j] = tmp  # 恢复

    # 输出结果
    for row in ans:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    solve()
```

