                    if (a[x][y] == 'R') {
                        int idx = x * m + y;
                        if (x > 0 && a[x-1][y] == 'R') {
                            unite(parent, idx, (x-1)*m + y);
                        }
                        if (y > 0 && a[x][y-1] == 'R') {
                            unite(parent, idx, x*m + (y-1));
                        }
