            int cnt = 0;
            for (int x = 0; x < n; ++x) {
                for (int y = 0; y < m; ++y) {
                    if (a[x][y] == 'R') {
                        int root = find(parent, x * m + y);
                        if (!seen[root]) {
                            seen[root] = true;
                            cnt++;
                        }
                    }
                }
            }
            ans[i][j] = cnt;
            a[i][j] = tmp;  // 恢复
